CREATE OR REPLACE FUNCTION swatch_billable_usage_update_last_modified_column()
  RETURNS TRIGGER AS $$
BEGIN
  -- Only assign CURRENT_TIMESTAMP when the statement did not set last_modified
  -- (e.g. preserve SET last_modified = updated_at during backfill).
  IF TG_OP = 'INSERT' THEN
    IF NEW.last_modified IS NULL THEN
      NEW.last_modified = CURRENT_TIMESTAMP;
    END IF;
  ELSIF NEW.last_modified IS NOT DISTINCT FROM OLD.last_modified THEN
    NEW.last_modified = CURRENT_TIMESTAMP;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_billable_usage_remittance_last_modified
      BEFORE INSERT OR UPDATE ON billable_usage_remittance
      FOR EACH ROW EXECUTE FUNCTION swatch_billable_usage_update_last_modified_column();

UPDATE billable_usage_remittance
      SET last_modified = updated_at
      WHERE last_modified IS NULL AND updated_at IS NOT NULL;
